/* Dark palette, matching the main Analytics page (Tailwind slate + the shared
   chart series colours used by the MA_/BH_ ECharts helpers). */
:root{
  --bg:#0f172a;          /* page ground   slate-900 */
  --card:#1e293b;        /* surface       slate-800 */
  --card2:#182234;       /* nested rows            */
  --line:#334155;        /* border        slate-700 */
  --line2:#293548;       /* faint row rule         */
  --ink:#e2e8f0;         /* body text     slate-200 */
  --ink2:#f1f5f9;        /* headings      slate-100 */
  --muted:#94a3b8;       /* secondary     slate-400 */
  --blue:#60a5fa; --teal:#34d399; --purple:#a78bfa;
  --green:#4ade80; --amber:#fbbf24; --red:#f87171; --cyan:#22d3ee;
  --shadow:0 4px 14px rgba(0,0,0,.35);
}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink);font:13px/1.4 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}
#root{padding:2px}
.grid{display:grid;gap:12px}
.kpis{grid-template-columns:repeat(4,1fr);margin-bottom:12px}
.two{grid-template-columns:1.45fr 1fr}
.three{grid-template-columns:1.05fr .9fr .95fr}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;box-shadow:var(--shadow);padding:13px;min-width:0}
.card h2{font-size:13px;margin:0 0 10px;color:var(--ink2)}
.kpi{display:flex;align-items:center;gap:11px;min-height:84px}
.bubble{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:rgba(96,165,250,.15);color:var(--blue);font-size:20px;flex:0 0 auto}
.bubble.teal{background:rgba(52,211,153,.15);color:var(--teal)}
.bubble.purple{background:rgba(167,139,250,.15);color:var(--purple)}
.bubble.warn{background:rgba(251,191,36,.15);color:var(--amber)}
.kpi b{font-size:21px;display:block;line-height:1.15;color:var(--ink2)}
.kpi small{color:var(--muted);display:block}
.up{color:var(--red)}.down{color:var(--green)}
.chart-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:6px}
.seg{display:flex;border:1px solid var(--line);border-radius:6px;overflow:hidden;flex:0 0 auto}
.seg button{border:0;border-right:1px solid var(--line);background:var(--card2);padding:5px 8px;color:var(--muted);cursor:pointer;font:inherit}
.seg button:last-child{border-right:0}
.seg button.active{background:var(--blue);color:#0f172a}
.chart{width:100%;height:230px;display:block}
.chart.sm{height:175px}
table{width:100%;border-collapse:collapse}
th{text-align:left;color:var(--muted);font-size:10px;font-weight:600;padding:7px;border-bottom:1px solid var(--line);white-space:nowrap}
td{padding:7px;border-bottom:1px solid var(--line2);white-space:nowrap;color:var(--ink)}
tr:last-child td{border-bottom:0}
.num{text-align:right;font-variant-numeric:tabular-nums}
.bar{height:8px;background:#0f172a;border-radius:6px;overflow:hidden;min-width:60px}
.bar i{display:block;height:100%;background:var(--blue);border-radius:6px}
.bar.teal i{background:var(--teal)}
.legend{display:flex;gap:13px;flex-wrap:wrap;color:var(--muted);font-size:10px;margin-top:8px}
.dot{display:inline-block;width:8px;height:8px;border-radius:2px;margin-right:4px}
.pill{display:inline-block;padding:3px 7px;border-radius:12px;font-size:10px}
.pill.red{background:rgba(248,113,113,.18);color:#fca5a5}
.pill.amber{background:rgba(251,191,36,.18);color:#fcd34d}
.pill.green{background:rgba(74,222,128,.18);color:#86efac}
.pill.grey{background:rgba(148,163,184,.18);color:#cbd5e1}
.scroll{overflow:auto;max-height:340px}
.scroll table{min-width:100%}
.matrix{overflow:auto;max-height:360px}
.cell{width:100%;height:18px;border-radius:3px;display:block}
.received{background:#34d399}.missing{background:#f87171}.late{background:#fbbf24}
.tree div{padding:6px 7px;border-bottom:1px solid var(--line2);display:flex;justify-content:space-between;gap:10px}
.tree strong{font-variant-numeric:tabular-nums;color:var(--ink2)}
.tree .l1{padding-left:20px;color:var(--muted)}
.tree .l2{padding-left:38px;color:var(--muted);font-size:11px}
.queue-row{display:grid;grid-template-columns:20px 1.8fr 1fr 70px 90px;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line2)}
.queue-row b{font-size:12px;display:block;color:var(--ink2)}
.queue-row small{display:block;color:var(--muted)}
.alert{font-size:15px}
.note{color:var(--muted);font-size:10px;margin-top:8px}
.gap{background:rgba(251,191,36,.08);border:1px dashed rgba(251,191,36,.45);border-radius:7px;padding:8px 10px;color:#fcd34d;font-size:11px;margin-top:8px}
.gap b{display:block;margin-bottom:2px}
.empty{padding:38px;text-align:center;color:var(--muted)}
.mapwrap{position:relative;height:285px;border-radius:7px;overflow:hidden;background:linear-gradient(140deg,#16233a,#111c2f);border:1px solid var(--line)}
.pin{position:absolute;border:2px solid #0f172a;background:var(--blue);border-radius:50%;box-shadow:0 2px 8px rgba(0,0,0,.6);transform:translate(-50%,-50%)}

