/* ---- shared rendering kit for the Energy Analytics views ----
   Every view is a custom widget fed by appsmith.model. No external libraries:
   the charts are hand-drawn SVG, so nothing has to load from a CDN. */

/* Dark palette, matching the main Analytics page. `grid`, `axis` and `band` are the
   chart furniture colours; everything else is the shared series palette its ECharts
   helpers use, so a series keeps the same colour across the old and new screens. */
var C = { blue:'#60a5fa', teal:'#34d399', purple:'#a78bfa', green:'#4ade80',
          amber:'#fbbf24', red:'#f87171', cyan:'#22d3ee', grey:'#94a3b8',
          grid:'#334155', axis:'#94a3b8', band:'rgba(96,165,250,.20)',
          bar:'rgba(96,165,250,.45)', ink:'#e2e8f0' };
var SERIES = ['#60a5fa','#34d399','#f472b6','#fbbf24','#a78bfa','#22d3ee',
              '#fb923c','#4ade80','#f87171','#c084fc','#facc15','#2dd4bf',
              '#818cf8','#fda4af'];

function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }

function money(n){
  var v = Number(n)||0, a = Math.abs(v), s = v<0?'-':'';
  if(a>=1e9) return s+'$'+(a/1e9).toFixed(2)+'B';
  if(a>=1e6) return s+'$'+(a/1e6).toFixed(2)+'M';
  if(a>=1e3) return s+'$'+Math.round(a/1e3)+'K';
  return s+'$'+a.toFixed(0);
}
function num(n,dp){
  var v = Number(n)||0, a = Math.abs(v), s = v<0?'-':'';
  if(a>=1e9) return s+(a/1e9).toFixed(1)+'B';
  if(a>=1e6) return s+(a/1e6).toFixed(1)+'M';
  if(a>=1e3) return s+(a/1e3).toFixed(1)+'K';
  return s+a.toFixed(dp==null?0:dp);
}
function pct(n,dp){ return (Number(n)||0).toFixed(dp==null?1:dp)+'%'; }

/* A delta reads red when it rises and green when it falls: for cost and consumption,
   up is bad. Views that want the opposite pass invert = true. */
function deltaHtml(d, invert){
  if(d==null || !isFinite(d)) return '<small>&nbsp;</small>';
  var up = d>0, good = invert ? up : !up;
  return '<small class="'+(good?'down':'up')+'">'+(up?'&uarr; ':'&darr; ')+pct(Math.abs(d))+'</small>';
}

function kpiStrip(kpis){
  if(!kpis || !kpis.length) return '';
  return '<div class="grid kpis">' + kpis.map(function(k){
    return '<div class="card kpi"><div class="bubble '+(k.tone||'')+'">'+esc(k.icon||'')+'</div>'+
      '<div><small>'+esc(k.label)+'</small><b>'+esc(k.value)+'</b>'+
      (k.delta!=null ? deltaHtml(k.delta)+'<small>'+esc(k.note||'')+'</small>'
                     : '<small>'+esc(k.note||'')+'</small>')+
      '</div></div>';
  }).join('') + '</div>';
}

/* ---- SVG primitives ----
   All charts draw into a fixed viewBox and scale with preserveAspectRatio, so they
   stay legible whatever width Appsmith gives the widget. */

function svgOpen(w,h,cls){
  return '<svg class="chart'+(cls?' '+cls:'')+'" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">';
}
