  if(!labels.length) return '<div class="empty">No data in this window</div>';
  var mx = scale([].concat.apply([], series.map(function(s){return s.values;})));
  var step = labels.length>1 ? (x1-x0)/(labels.length-1) : 0;
  var out = svgOpen(w,h) + gridLines(x0,y0,y1,x1,4);

