  out += '<div class="card"><h2>Warnings over time</h2>' +
    stackedBars(ot.map(function(p){return p.label;}), [
      {name:'Info',     color:C.blue,  values:ot.map(function(p){return p.Info;})},
      {name:'Warning',  color:C.amber, values:ot.map(function(p){return p.Warning;})},
      {name:'Critical', color:C.red,   values:ot.map(function(p){return p.Critical;})}
    ]) +
    legend([{name:'Critical',color:C.red},{name:'Warning',color:C.amber},{name:'Info',color:C.blue}]) +
    '<div class="note">Severity buckets: Critical 40+, Warning 30, Info 20 and below.</div></div>';

  var q = (m.queue||[]).slice(0,12);
  var mark = {Critical:'<span class="alert" style="color:var(--red)">&#9670;</span>',
              Warning:'<span class="alert" style="color:var(--amber)">&#9650;</span>',
              Info:'<span class="alert" style="color:var(--blue)">&#9679;</span>'};
  out += '<div class="card"><h2>Needs attention</h2>' +
    (q.length ? '<div class="scroll">' + q.map(function(r){
      return '<div class="queue-row">' + (mark[r.severity]||'') +
        '<div><b>'+esc(r.title)+'</b><small>'+esc(r.location)+' · '+esc(r.category)+'</small></div>' +
        '<div>'+money(r.amount)+'<small>bill total</small></div>' +
        '<div>'+esc(r.date)+'</div>' +
        '<div><span class="pill '+(r.severity==='Critical'?'red':r.severity==='Warning'?'amber':'grey')+'">'+
          esc(r.severity)+'</span></div></div>';
    }).join('') + '</div>' : '<div class="empty">Nothing open in this window</div>') +
    gapNote(m.gaps) + '</div>';
  out += '</div>';

  out += '<div class="grid two" style="margin-top:12px">';

  var imp = (m.impacted||[]).slice(0,10);
  out += '<div class="card"><h2>Impacted locations</h2><div class="scroll"><table>' +
    '<thead><tr><th>Location</th><th class="num">Open</th><th class="num">Critical</th><th class="num">Bill value</th></tr></thead><tbody>' +
    (imp.length ? imp.map(function(r){
      return '<tr><td>'+esc(r.location)+'</td><td class="num">'+r.open+
        '</td><td class="num'+(r.critical?' up':'')+'">'+r.critical+
        '</td><td class="num">'+money(r.amount)+'</td></tr>';
    }).join('') : '<tr><td colspan="4" class="empty">No impacted locations</td></tr>') +
    '</tbody></table></div>' +
    '<div class="note">Bill value is the total amount on the flagged bills, not a quantified loss.</div></div>';

  var lf = m.lateFees||{gross:0,recouped:0,net:0,byLocation:[],bills:0,excluded:0};
  var mxL = (lf.byLocation||[]).length ? lf.byLocation[0].fee : 0;
  out += '<div class="card"><h2>Late fee exposure</h2>' +
    '<b style="font-size:27px">'+money(lf.net)+'</b> <small>net over the window</small>' +
    '<table style="margin-top:10px">' +
      '<tr><td>Late fees charged</td><td class="num">'+money(lf.gross)+'</td></tr>' +
      '<tr><td>Recouped</td><td class="num">'+money(lf.recouped)+'</td></tr>' +
      '<tr><td>Bills affected</td><td class="num">'+num(lf.bills)+'</td></tr>' +
    '</table>' +
    ((lf.byLocation||[]).length
      ? '<table style="margin-top:8px">' + lf.byLocation.slice(0,5).map(function(r){
          return barRow(r.location, r.fee, mxL, money(r.fee));
        }).join('') + '</table>'
      : '') +
    '<div class="note">Live, processed bills only' +
      (lf.excluded ? ' — '+num(lf.excluded)+' unfinalised bill(s) excluded' : '') +
      '. Dropping either filter inflates the total past UBM.</div></div>';

  out += '</div>';
  return out;
});
